1	export type QueueState = "idle" | "running" | "succeeded" | "failed" | "paused";
2	export function stateAfter(result: "started" | "ok" | "error" | "pause"): QueueState {
3	  return { started: "running", ok: "succeeded", error: "failed", pause: "paused" }[result] as QueueState;
4	}
5

1	import type { QueueState } from "./queue";
2	export const statusVisuals = {
3	  idle: { label: "Start", path: "assets/start.svg", frames: 1 },
4	  running: { label: "Working", path: "assets/working.png", frames: 4 },
5	  paused: { label: "Paused", path: "assets/paused.png", frames: 1 },
6	  succeeded: { label: "Ready", path: "assets/ready-confirmed.png", frames: 1 },
7	  failed: { label: "Retry", path: "assets/error-retry.png", frames: 1 },
8	};
9	export const display = { cell: [16, 16], scale: 3, filter: "nearest", frameMs: 100, background: "#172336" };
10	export function statusCell(state: QueueState) { return statusVisuals[state]; }
11	export function compactStatus(state: QueueState) { return statusVisuals[state]; }
12	export function accountBadge(registry: Record<string, string>, account: string) {
13	  return registry[account]; // Provided by the service; not enumerable in this checkout.
14	}
15

1	// Successor of queue-view.ts for the reduced-motion requirement. queue-view.ts is retained unchanged.
2	// Same backend state machine (./queue), same shared statusVisuals map and the same two consumers.
3	import type { QueueState } from "./queue";
4	export type MotionPreference = "normal" | "reduced";
5	export const reducedMotionQuery = "(prefers-reduced-motion: reduce)";
6	export const statusVisuals = {
7	  idle: { label: "Start", path: "assets/start.svg", frames: 1, still: 0 },
8	  running: { label: "Working", path: "assets/working.png", frames: 4, still: 0 },
9	  paused: { label: "Paused", path: "assets/paused.png", frames: 1, still: 0 },
10	  succeeded: { label: "Ready", path: "assets/ready-confirmed.png", frames: 1, still: 0 },
11	  failed: { label: "Retry", path: "assets/error-retry.png", frames: 1, still: 0 },
12	};
13	export const display = { cell: [16, 16], scale: 3, filter: "nearest", frameMs: 100, background: "#172336" };
14	// `frames` is always the sheet's cell count (geometry); `still` is the cell held when motion is reduced.
15	export type StatusVisual = (typeof statusVisuals)[QueueState];
16	export type StatusDescriptor = StatusVisual & { motion: MotionPreference; animate: boolean; holdFrame: number | null };
17	export function motionPreference(query: { matches: boolean } | null | undefined = globalThis.matchMedia?.(reducedMotionQuery)): MotionPreference {
18	  return query?.matches ? "reduced" : "normal";
19	}
20	export function describe(visual: StatusVisual, motion: MotionPreference): StatusDescriptor {
21	  const animate = motion === "normal" && visual.frames > 1;
22	  return { ...visual, motion, animate, holdFrame: animate ? null : visual.still };
23	}
24	export function frameAt(descriptor: StatusDescriptor, elapsed: number) {
25	  return descriptor.animate ? Math.floor(Math.max(elapsed, 0) / display.frameMs) % descriptor.frames : descriptor.holdFrame ?? 0;
26	}
27	export function statusCell(state: QueueState, motion: MotionPreference = motionPreference()) { return describe(statusVisuals[state], motion); }
28	export function compactStatus(state: QueueState, motion: MotionPreference = motionPreference()) { return describe(statusVisuals[state], motion); }
29	export function accountBadge(registry: Record<string, string>, account: string) {
30	  return registry[account]; // Provided by the service; not enumerable in this checkout.
31	}
32

1	// Successor fixture: executes the actual src/queue.ts and src/queue-view-successor.ts modules and follows the
2	// prefers-reduced-motion media query, including changes while the page stays open. renderer/view.mjs is retained unchanged.
3	import { stateAfter } from '/src/queue.ts';
4	import { statusVisuals, statusCell, compactStatus, display, reducedMotionQuery, motionPreference, frameAt } from '/src/queue-view-successor.ts';
5	
6	const panel = display.background;
7	document.documentElement.style.setProperty('--panel', panel);
8	const sessionId = crypto.randomUUID(); // Same value across every capture of one open page: proves no reload between preference switches.
9	const cache = new Map();
10	const decoded = new Map();
11	const cells = [];
12	const consumers = { statusCell, compactStatus };
13	const media = matchMedia(reducedMotionQuery);
14	let motion = motionPreference(media);
15	const preferenceEvents = [];
16	const events = ['idle', 'started', 'pause', 'ok', 'error'].filter(event => event === 'idle' || statusVisuals[stateAfter(event)]);
17	document.querySelectorAll('[data-event]').forEach(button => { button.hidden = !events.includes(button.dataset.event); });
18	const errors = [];
19	window.addEventListener('error', event => errors.push(event.message));
20	window.addEventListener('unhandledrejection', event => errors.push(String(event.reason)));
21	const digest = async bytes => [...new Uint8Array(await crypto.subtle.digest('SHA-256', bytes))].map(x => x.toString(16).padStart(2, '0')).join('');
22	const motionText = () => `Motion: ${motion} (${reducedMotionQuery} ${media.matches ? 'matches' : 'does not match'})`;
23	document.querySelector('#motion').textContent = motionText();
24	
25	async function imageFor(path) {
26	  if (!cache.has(path)) cache.set(path, (async () => {
27	    const response = await fetch(`/${path}`);
28	    if (!response.ok) { const asset = { available: false, status: response.status, path }; decoded.set(path, asset); return asset; }
29	    const data = await response.arrayBuffer();
30	    const image = new Image();
31	    const url = URL.createObjectURL(new Blob([data], { type: response.headers.get('Content-Type') }));
32	    try { image.src = url; await image.decode(); }
33	    finally { URL.revokeObjectURL(url); }
34	    const asset = { available: true, image, path, sha256: await digest(data), width: image.naturalWidth, height: image.naturalHeight };
35	    decoded.set(path, asset);
36	    return asset;
37	  })());
38	  return cache.get(path);
39	}
40	
41	function paint(canvas, asset, descriptor, scale, elapsed) {
42	  const [width, height] = display.cell;
43	  const frame = frameAt(descriptor, elapsed);
44	  const context = canvas.getContext('2d', { willReadFrequently: true });
45	  context.imageSmoothingEnabled = display.filter !== 'nearest';
46	  context.fillStyle = panel;
47	  context.fillRect(0, 0, canvas.width, canvas.height);
48	  if (asset.available && asset.width === width * descriptor.frames && asset.height === height) {
49	    context.drawImage(asset.image, frame * width, 0, width, height, 0, 0, width * scale, height * scale);
50	  }
51	  return frame;
52	}
53	
54	const publicDescriptor = descriptor => ({ ...descriptor });
55	
56	async function makeCell(consumer, state, scale, elapsed = 0, track = true) {
57	  const descriptor = consumers[consumer](state, motion);
58	  const asset = await imageFor(descriptor.path);
59	  const node = document.createElement('div');
60	  node.className = `cell ${consumer === 'compactStatus' ? 'compact' : ''}`;
61	  const glyph = document.createElement('span'); glyph.className = 'glyph';
62	  const label = document.createElement('span'); label.textContent = descriptor.label;
63	  node.append(glyph, label);
64	  const info = { consumer, state, scale, motion, descriptor: publicDescriptor(descriptor), asset: { ...asset, image: undefined }, node, canvas: null, frame: 0 };
65	  if (asset.available) {
66	    const canvas = document.createElement('canvas');
67	    canvas.width = display.cell[0] * scale; canvas.height = display.cell[1] * scale;
68	    canvas.setAttribute('aria-label', `${descriptor.label} icon`);
69	    info.canvas = canvas; info.frame = paint(canvas, asset, descriptor, scale, elapsed);
70	    info.geometryMatches = asset.width === display.cell[0] * descriptor.frames && asset.height === display.cell[1];
71	    glyph.append(canvas);
72	    if (!info.geometryMatches) { const warning = document.createElement('span'); warning.className = 'missing'; warning.textContent = 'Wrong sheet size'; node.append(warning); }
73	  } else {
74	    glyph.classList.add('missing'); glyph.textContent = 'Missing asset';
75	  }
76	  if (track) cells.push(info);
77	  return info;
78	}
79	
80	// Re-derive a tracked cell from the same consumer under the current preference and repaint it in place.
81	function refresh(cell, elapsed) {
82	  const descriptor = consumers[cell.consumer](cell.state, motion);
83	  cell.descriptor = publicDescriptor(descriptor); cell.motion = motion;
84	  const asset = decoded.get(descriptor.path);
85	  if (cell.canvas && asset) cell.frame = paint(cell.canvas, asset, descriptor, cell.scale, elapsed);
86	  return { consumer: cell.consumer, state: cell.state, scale: cell.scale, live: liveCells.includes(cell), animate: descriptor.animate, holdFrame: descriptor.holdFrame, frame: cell.frame };
87	}
88	
89	const matrix = document.querySelector('#matrix');
90	for (const text of ['State', 'Full · 1×', `Full · ${display.scale}×`, 'Compact · 1×', `Compact · ${display.scale}×`]) {
91	  const node = document.createElement('div'); node.className = 'heading'; node.textContent = text; matrix.append(node);
92	}
93	for (const state of Object.keys(statusVisuals)) {
94	  const label = document.createElement('div'); label.className = 'row-label'; label.textContent = state; matrix.append(label);
95	  for (const consumer of Object.keys(consumers)) for (const scale of [1, display.scale]) matrix.append((await makeCell(consumer, state, scale)).node);
96	}
97	const missing = [...cache.keys()].filter(path => !cells.find(cell => cell.descriptor.path === path)?.asset.available);
98	document.querySelector('#coverage').textContent = missing.length ? `${missing.length} status assets are still missing: ${missing.join(', ')}` : 'Every mapped status asset is available; visual review remains separate.';
99	
100	let livePromise;
101	let liveCells = [];
102	let origin = performance.now();
103	async function select(event) {
104	  const state = event === 'idle' ? 'idle' : stateAfter(event);
105	  liveCells = await Promise.all(Object.keys(consumers).map(consumer => makeCell(consumer, state, display.scale, 0, false)));
106	  document.querySelector('#live').replaceChildren(...liveCells.map(cell => cell.node));
107	  document.querySelector('#live-title').textContent = `Current queue state · ${state}`;
108	  origin = performance.now();
109	  return { event, state, motion, consumers: liveCells.map(({ consumer, descriptor, asset }) => ({ consumer, descriptor, available: asset.available, sha256: asset.sha256 })) };
110	}
111	document.querySelectorAll('[data-event]').forEach(button => button.addEventListener('click', () => { livePromise = select(button.dataset.event); }));
112	await select('ok');
113	
114	media.addEventListener('change', () => {
115	  const before = motion;
116	  motion = motionPreference(media);
117	  const now = performance.now();
118	  const repainted = [...cells, ...liveCells].map(cell => refresh(cell, cell.scale === display.scale && liveCells.includes(cell) ? now - origin : 0));
119	  document.querySelector('#motion').textContent = motionText();
120	  preferenceEvents.push({ at: now, sessionId, matches: media.matches, from: before, to: motion, repainted });
121	});
122	
123	function animate(now) {
124	  for (const cell of liveCells) if (cell.canvas && cell.descriptor.animate) {
125	    const asset = decoded.get(cell.descriptor.path);
126	    if (asset) cell.frame = paint(cell.canvas, asset, cell.descriptor, cell.scale, now - origin);
127	  }
128	  requestAnimationFrame(animate);
129	}
130	requestAnimationFrame(animate);
131	
132	async function capture() {
133	  await document.fonts.ready;
134	  const transitions = [];
135	  for (const event of events) {
136	    const button = document.querySelector(`[data-event="${event}"]`);
137	    button.click(); transitions.push(await livePromise);
138	  }
139	  document.querySelector('[data-event="started"]').click(); await livePromise;
140	  await new Promise(resolve => setTimeout(resolve, 250)); // Let the live loop run under the current preference before sampling.
141	  const timeline = [];
142	  for (const state of Object.keys(statusVisuals)) {
143	    if (statusVisuals[state].frames <= 1) continue;
144	    const boundaries = Array.from({ length: statusVisuals[state].frames }, (_, i) => [i * display.frameMs, (i + 1) * display.frameMs - 1]).flat();
145	    for (const consumer of Object.keys(consumers)) for (const elapsed of [...boundaries, display.frameMs * statusVisuals[state].frames]) {
146	      const cell = await makeCell(consumer, state, 1, elapsed, false);
147	      timeline.push({ consumer, state, motion, elapsed, available: cell.asset.available, descriptor: cell.descriptor, frame: cell.canvas ? cell.frame : null, png: cell.canvas?.toDataURL() });
148	    }
149	  }
150	  const snapshot = ({ node, canvas, ...info }) => ({ ...info, canvas: undefined,
151	    smoothing: canvas?.getContext('2d').imageSmoothingEnabled,
152	    bounds: canvas ? Object.fromEntries(['x', 'y', 'width', 'height'].map(key => [key, canvas.getBoundingClientRect()[key]])) : null,
153	    imageRendering: canvas ? getComputedStyle(canvas).imageRendering : null,
154	    png: canvas?.toDataURL(),
155	  });
156	  const views = cells.map(snapshot);
157	  const live = liveCells.map(cell => ({ ...snapshot(cell), elapsed: performance.now() - origin }));
158	  return { version: 2, sessionId, userAgent: navigator.userAgent, devicePixelRatio, viewport: { width: innerWidth, height: innerHeight, clientWidth: document.documentElement.clientWidth }, display, reducedMotionQuery,
159	    motion, mediaMatches: media.matches, motionText: document.querySelector('#motion').textContent, preferenceEvents: preferenceEvents.map(event => ({ ...event })), transitions, timeline, views, live, missing, errors,
160	    scope: 'Actual browser execution of the successor queue modules, decode, canvas crop/scale/compositing, DOM event handlers and the prefers-reduced-motion media query. Image provenance and visual/style acceptance are separate.' };
161	}
162	window.captureQueue = capture;
163	window.queueMotion = () => ({ sessionId, motion, matches: media.matches, events: preferenceEvents.length });
164	document.body.dataset.ready = 'true';
165	if (new URL(location.href).searchParams.has('capture')) {
166	  const report = await capture();
167	  await fetch('/__capture', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(report) });
168	  document.body.dataset.captureComplete = 'true';
169	}
170

