S=16
big = Image.new("RGBA",(16*S,16*S),(0,0,0,0))
ImageDraw.Draw(big).polygon([(4*S,2*S),(14*S,8*S),(4*S,14*S)], fill=(0x70,0xb9,0xed,255))
start = big.resize((16,16), Image.Resampling.BOX)
start.save(out/"specialist-start-raster-16.png")
def composite(img):
    base = Image.new("RGBA", img.size, PANEL); return Image.alpha_composite(base, img)
def gray(img):
    g = img.convert("L").convert("RGBA"); return g
items = [("W0",cells[0]),("W1",cells[1]),("W2",cells[2]),("W3",cells[3]),("Ready",ready),("Paused",paused),("Retry",retry),("Start",start)]
for scale in (1,3,12):
    for mode in ("color","gray"):
        gap = 4*scale if scale<12 else 24
        lab_h = 0 if scale<12 else 16
        w = len(items)*(16*scale)+(len(items)+1)*gap
        h = 16*scale+2*gap+lab_h
        sheet = Image.new("RGBA",(w,h),PANEL)
        d = ImageDraw.Draw(sheet)
        x=gap
        for name,img in items:
            c = composite(img)
            if mode=="gray": c = gray(c)
            c = c.resize((16*scale,16*scale), Image.Resampling.NEAREST)
            sheet.paste(c,(x,gap))
            if lab_h: d.text((x,gap+16*scale+2), name, fill=(220,220,220,255))
            x += 16*scale+gap
        sheet.save(out/f"specialist-family-{mode}-{scale}x.png")
# Also an isolated cell0 vs Ready vs Paused at 3x with grid at 12x for cell0 only
c0 = composite(cells[0]).resize((16*20,16*20), Image.Resampling.NEAREST)
d = ImageDraw.Draw(c0)
for i in range(17):
    d.line([(i*20,0),(i*20,320)], fill=(60,70,90,255)); d.line([(0,i*20),(320,i*20)], fill=(60,70,90,255))
