    for y in range(16):
        print("  "+"".join("#" if px[x,y][3]==255 else ("." if px[x,y][3]==0 else "o") for x in range(16)))
print("ready alpha map"); px=ready.load()
for y in range(16): print("  "+"".join("#" if px[x,y][3]==255 else ("." if px[x,y][3]==0 else "o") for x in range(16)))
print("paused alpha map"); px=paused.load()
for y in range(16): print("  "+"".join("#" if px[x,y][3]==255 else ("." if px[x,y][3]==0 else "o") for x in range(16)))
print("retry alpha map"); px=retry.load()
for y in range(16): print("  "+"".join("#" if px[x,y][3]==255 else ("." if px[x,y][3]==0 else "o") for x in range(16)))
print("start raster alpha map (AA, box-downsampled)"); px=start.load()
for y in range(16): print("  "+"".join("#" if px[x,y][3]==255 else ("." if px[x,y][3]==0 else "o") for x in range(16)))
# distinct visible colours per cell
for idx,c in enumerate(cells):
    cols = {}
    for p in c.getdata():
        if p[3]>0: cols[p]=cols.get(p,0)+1
    print(f"cell{idx} visible px {sum(cols.values())} colours {len(cols)}:", sorted(cols.items(), key=lambda kv:-kv[1]))
# rotation check cw: cell k == rot90 cw ^k of cell0 on RGBA for visible
def rot_cw(img): return img.transpose(Image.Transpose.ROTATE_270)
r = cells[0]
for k in range(1,4):
    r = rot_cw(r)
    a = [p if p[3] else (0,0,0,0) for p in r.getdata()]; b=[p if p[3] else (0,0,0,0) for p in cells[k].getdata()]
    print(f"cell{k} == cw^{k}(cell0) on visible RGBA:", a==b)
# transparent pixel RGB values
tr = {}
for p in working.getdata():
    if p[3]==0: tr[p]=tr.get(p,0)+1
print("transparent RGB in working.png:", tr)
# luminance of visible colours (grayscale check)
def lum(p): return round(0.299*p[0]+0.587*p[1]+0.114*p[2])
print("panel lum", lum(PANEL))
for name,img in items:
