1	// Fresh isolated browser capture driven over the DevTools protocol so the prefers-reduced-motion preference can be
2	// switched while the same page stays open. No production/profile-wide browser configuration is touched.
3	// Usage: node renderer-successor/capture.mjs --out NEW_DIR [--project ROOT] [--browser PATH] [--phases a,b,c] [--chrome-flag FLAG]...
4	// Phases: normal-start (no emulation), reduced (emulate prefers-reduced-motion: reduce), normal-restored (emulate no-preference),
5	//         as-launched (no emulation; use with --chrome-flag --force-prefers-reduced-motion to test the startup preference).
6	import { spawn } from 'node:child_process';
7	import { access, mkdir, readFile, writeFile, mkdtemp, realpath, rm } from 'node:fs/promises';
8	import { resolve, join, relative, sep } from 'node:path';
9	import { tmpdir } from 'node:os';
10	import { serve, rendererRoot, hash } from './server.mjs';
11	
12	const argv = process.argv.slice(2);
13	const option = name => { const i = argv.indexOf(name); return i < 0 ? null : argv[i + 1]; };
14	const options = name => argv.flatMap((value, i) => value === name ? [argv[i + 1]] : []);
15	const project = resolve(option('--project') || join(rendererRoot, '..'));
16	const output = option('--out');
17	if (!output) throw new Error('Use --out NEW_DIRECTORY to retain a fresh capture');
18	const out = resolve(output);
19	await mkdir(out, { recursive: false });
20	const phases = (option('--phases') || 'normal-start,reduced,normal-restored').split(',');
21	const extraFlags = options('--chrome-flag');
22	let browser = option('--browser');
23	if (!browser) {
24	  for (const file of [join(process.env.PROGRAMFILES || '', 'Google/Chrome/Application/chrome.exe'), join(process.env['ProgramFiles(x86)'] || '', 'Microsoft/Edge/Application/msedge.exe')]) {
25	    try { await access(file); browser = file; break; } catch { /* Try next installed browser. */ }
26	  }
27	}
28	if (!browser) throw new Error('No local Chromium browser found; pass --browser PATH');
29	const profileParent = await realpath(tmpdir());
30	const profile = await mkdtemp(join(profileParent, 'pixl-render-successor-'));
31	const rendererFiles = Object.fromEntries(await Promise.all(['server.mjs', 'capture.mjs', 'index.html', 'view.mjs', 'check.py'].map(async name => [name, hash(await readFile(join(rendererRoot, name)))])));
32	const running = await serve(project, null);
33	const args = ['--headless=new', '--disable-gpu', '--hide-scrollbars', '--no-first-run', '--no-default-browser-check', '--disable-background-networking', '--force-device-scale-factor=1', `--user-data-dir=${profile}`, '--window-size=1280,1000', '--remote-debugging-port=0', '--remote-allow-origins=*', ...extraFlags, 'about:blank'];
34	await writeFile(join(out, 'launch.json'), JSON.stringify({ browser, args, phases, project, node: process.version, url: running.url, scope: 'Isolated local fixture renderer driven over the DevTools protocol' }, null, 2) + '\n');
35	const sleep = ms => new Promise(resolve => setTimeout(resolve, ms));
36	let child, stdout = '', stderr = '';
37	const result = { phases: [] };
38	try {
39	  child = spawn(browser, args, { windowsHide: true, stdio: ['ignore', 'pipe', 'pipe'] });
40	  child.stdout.on('data', chunk => { stdout += chunk; }); child.stderr.on('data', chunk => { stderr += chunk; });
41	  let port = null;
42	  for (let i = 0; i < 100 && port === null; i++) {
43	    try { port = Number((await readFile(join(profile, 'DevToolsActivePort'), 'utf8')).split('\n')[0]); } catch { await sleep(150); }
44	  }
45	  if (!port) throw new Error('Browser did not publish a DevTools port');
46	  let targets = [];
47	  for (let i = 0; i < 50 && !targets.find(t => t.type === 'page'); i++) {
48	    try { targets = await (await fetch(`http://127.0.0.1:${port}/json/list`)).json(); } catch { /* retry */ }
49	    if (!targets.find(t => t.type === 'page')) await sleep(100);
50	  }
51	  const page = targets.find(t => t.type === 'page');
52	  if (!page) throw new Error('No page target');
53	  const ws = new WebSocket(page.webSocketDebuggerUrl);
54	  await new Promise((yes, no) => { ws.addEventListener('open', yes, { once: true }); ws.addEventListener('error', no, { once: true }); });
55	  let nextId = 1; const pending = new Map();
56	  ws.addEventListener('message', event => { const message = JSON.parse(event.data); if (message.id && pending.has(message.id)) { const { yes, no } = pending.get(message.id); pending.delete(message.id); message.error ? no(new Error(JSON.stringify(message.error))) : yes(message.result); } });
57	  const send = (method, params = {}) => new Promise((yes, no) => { const id = nextId++; pending.set(id, { yes, no }); ws.send(JSON.stringify({ id, method, params })); });
58	  const evaluate = async (expression, awaitPromise = false) => {
59	    const { result: value, exceptionDetails } = await send('Runtime.evaluate', { expression, awaitPromise, returnByValue: true });
60	    if (exceptionDetails) throw new Error('Page evaluation failed: ' + JSON.stringify(exceptionDetails).slice(0, 2000));
61	    return value.value;
62	  };
63	  await send('Page.enable'); await send('Runtime.enable');
64	  await send('Emulation.setDeviceMetricsOverride', { width: 1280, height: 1000, deviceScaleFactor: 1, mobile: false });
65	  await send('Page.navigate', { url: `${running.url}/` });
66	  for (let i = 0; i < 200 && !(await evaluate("document.body?.dataset.ready === 'true'")); i++) await sleep(50);
67	  if (!(await evaluate("document.body?.dataset.ready === 'true'"))) throw new Error('Page did not become ready');
68	  const emulate = value => send('Emulation.setEmulatedMedia', { media: '', features: [{ name: 'prefers-reduced-motion', value }] });
69	  const waitMotion = async expected => {
70	    for (let i = 0; i < 60; i++) { const state = await evaluate('window.queueMotion()'); if (state.motion === expected) return state; await sleep(50); }
71	    throw new Error(`Preference did not switch to ${expected}`);
72	  };
73	  let index = 0;
74	  for (const phase of phases) {
75	    let emulated = null;
76	    if (phase === 'reduced') { await emulate('reduce'); emulated = 'reduce'; await waitMotion('reduced'); }
77	    else if (phase === 'normal-restored') { await emulate('no-preference'); emulated = 'no-preference'; await waitMotion('normal'); }
78	    else if (phase !== 'normal-start' && phase !== 'as-launched') throw new Error(`Unknown phase ${phase}`);
79	    await sleep(450); // Let the live loop run under this preference before sampling.
80	    const motionBefore = await evaluate('window.queueMotion()');
81	    const report = await evaluate('window.captureQueue()', true);
82	    const screenshotData = Buffer.from((await send('Page.captureScreenshot', { format: 'png', captureBeyondViewport: false })).data, 'base64');
83	    const screenshotName = `${phase}-destination.png`;
84	    await writeFile(join(out, screenshotName), screenshotData);
85	    for (const item of [...report.views, ...report.live, ...report.timeline]) if (item.png) {
86	      const bytes = Buffer.from(item.png.split(',')[1], 'base64');
87	      const name = `view-${String(index++).padStart(3, '0')}.png`;
88	      await writeFile(join(out, name), bytes); item.image = { path: name, sha256: hash(bytes) }; delete item.png;
89	    }
90	    result.phases.push({ name: phase, emulated, motionBefore, screenshot: { path: screenshotName, sha256: hash(screenshotData) }, report });
91	  }
92	  ws.close();
93	  result.version = 2; result.browser = browser; result.args = args; result.node = process.version; result.url = running.url;
94	  result.served_files = Object.fromEntries(running.served);
95	  for (const [name, expected] of Object.entries(rendererFiles)) if (hash(await readFile(join(rendererRoot, name))) !== expected) throw new Error(`Renderer changed during capture: ${name}`);
96	  result.renderer_files = rendererFiles;
97	  result.observed_at = new Date().toISOString();
98	  result.scope = 'One isolated headless page, no reload between phases; prefers-reduced-motion switched through DevTools media emulation where a phase says so. Mechanical fixture evidence only.';
99	  await writeFile(join(out, 'render.json'), JSON.stringify(result, null, 2) + '\n');
100	  console.log(JSON.stringify({ capture: join(out, 'render.json'), phases: result.phases.map(p => ({ name: p.name, motion: p.report.motion, errors: p.report.errors, missing: p.report.missing, events: p.report.preferenceEvents.length })) }));
101	} finally {
102	  if (child) { child.kill(); await new Promise(resolve => { child.once('exit', resolve); setTimeout(resolve, 5000); }); }
103	  await writeFile(join(out, 'browser-process.json'), JSON.stringify({ stdout, stderr, exitCode: child?.exitCode ?? null }, null, 2) + '\n');
104	  running.server.closeAllConnections(); await new Promise(resolve => running.server.close(resolve));
105	  // Only remove this process's own resolved temporary profile, never a user profile.
106	  const actual = await realpath(profile);
107	  const within = relative(profileParent, actual);
108	  if (within.startsWith('pixl-render-successor-') && !within.includes(sep) && actual === resolve(profile)) {
109	    try { await rm(actual, { recursive: true, maxRetries: 4, retryDelay: 250 }); } catch { /* OS-held cache may outlive the browser. */ }
110	  }
111	}
